export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const num=(v,d=0)=>v===null||v===undefined||!Number.isFinite(v)?'—':v.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
export const usd=(v,d=0)=>v===null||v===undefined||!Number.isFinite(v)?'—':'$'+num(v,d);
export const pct=v=>v===null||v===undefined||!Number.isFinite(v)?'—':num(v*100,2)+'%';
export const palette=['#255bd7','#e06048','#087d84','#8b62bf','#d39a22','#526b92','#c85891'];
export function bars(items,{key='cost',format=usd,title='渠道花费',limit=10}={}){const sorted=[...items].sort((a,b)=>(b[key]??-Infinity)-(a[key]??-Infinity)).slice(0,limit);const max=Math.max(1,...sorted.map(r=>Math.abs(r[key]||0)));return `<div class="bar-chart" role="img" aria-label="${esc(title)}">${sorted.map((r,i)=>`<div class="bar-row"><div class="bar-label"><span title="${esc(r.name)}">${esc(r.name)}</span><strong>${format(r[key])}</strong></div><div class="bar-track"><div style="width:${Math.max(0,(Math.abs(r[key]||0)/max)*100)}%;background:${palette[i%palette.length]}"></div></div></div>`).join('')}</div><p class="chart-caption">按${esc(title)}排序 · 数值来自当前筛选范围${items.length>limit?` · 显示前 ${limit} 项`:''}</p>`}
export function scatter(groups,overall){const valid=groups.filter(g=>g.cpc!==null&&g.cvr!==null);const W=760,H=420,L=70,R=30,T=40,B=60;const maxX=Math.max(.1,...valid.map(g=>g.cpc))*1.27,maxY=Math.max(.001,...valid.map(g=>g.cvr))*1.25;const x=v=>L+v/maxX*(W-L-R),y=v=>H-B-v/maxY*(H-T-B);const refX=x(overall.cpc||0),refY=y(overall.cvr||0);const maxSpend=Math.max(1,...valid.map(g=>g.cost));let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-labelledby="scatter-title scatter-desc"><title id="scatter-title">渠道点击成本与预订率四象限</title><desc id="scatter-desc">横轴为 CPC，纵轴为预订量除以点击。气泡面积表示花费。虚线表示整体加权值。相同数值可在配套渠道表查看。</desc><rect x="${L}" y="${T}" width="${refX-L}" height="${refY-T}" fill="#eaf6f3"/><rect x="${refX}" y="${refY}" width="${W-R-refX}" height="${H-B-refY}" fill="#fff2f0"/>`;for(let i=0;i<=4;i++){const xx=L+i/4*(W-L-R),yy=H-B-i/4*(H-T-B);svg+=`<line x1="${L}" y1="${yy}" x2="${W-R}" y2="${yy}" stroke="#e5eaf1"/><text x="${L-12}" y="${yy+4}" text-anchor="end">${pct(maxY*i/4)}</text><text x="${xx}" y="${H-B+27}" text-anchor="middle">${usd(maxX*i/4,2)}</text>`}svg+=`<line x1="${refX}" y1="${T}" x2="${refX}" y2="${H-B}" stroke="#8292ab" stroke-dasharray="5 5"/><line x1="${L}" y1="${refY}" x2="${W-R}" y2="${refY}" stroke="#8292ab" stroke-dasharray="5 5"/><text x="${L}" y="22" class="axis-title">预订 / 点击（CVR）↑</text><text x="${W-R}" y="${H-12}" text-anchor="end" class="axis-title">点击成本 CPC（USD）→</text>`;valid.forEach((g,i)=>{const radius=Math.sqrt(g.cost/maxSpend)*24;svg+=`<g><circle cx="${x(g.cpc)}" cy="${y(g.cvr)}" r="${radius}" fill="${palette[i%palette.length]}" fill-opacity=".72" stroke="white" stroke-width="2"><title>${esc(g.name)}：CPC ${usd(g.cpc,2)}；CVR ${pct(g.cvr)}；花费 ${usd(g.cost)}</title></circle><text x="${x(g.cpc)+(radius<10?radius+6:0)}" y="${y(g.cvr)+4}" fill="${radius<10?'#24334d':'white'}" text-anchor="${radius<10?'start':'middle'}" style="font-size:11px;font-weight:700">${i+1}</text></g>`});svg+='</svg>';return `<div class="scatter">${svg}</div><div class="chart-legend">${valid.map((g,i)=>`<span><i style="background:${palette[i%palette.length]}"></i>${i+1}. ${esc(g.name)}</span>`).join('')}</div><p class="chart-caption">参考线：加权 CPC ${usd(overall.cpc,2)} / CVR ${pct(overall.cvr)}。气泡面积 ∝ 广告花费；象限用于诊断，不代表因果结论。</p>`}
export function metricCards(t){return `<div class="metric-grid">${[['广告花费',usd(t.cost,2),'Total Cost'],['预订量',num(t.bookings),'Total Volume of Bookings'],['销售收入',usd(t.revenue,2),'Amount'],['广告销售回报',num(t.roas,2)+'×','销售收入 / 广告花费']].map(([l,v,n])=>`<div class="metric-card"><span>${l}</span><strong>${v}</strong><small>${n}</small></div>`).join('')}</div>`}
export function metricsTable(rows,{caption='渠道经营指标',showPublisher=false}={}){return `<div class="table-scroll"><table><caption>${esc(caption)}</caption><thead><tr><th scope="col">${showPublisher?'活动':'渠道'}</th><th scope="col">广告花费</th><th scope="col">曝光</th><th scope="col">点击</th><th scope="col">CTR</th><th scope="col">预订</th><th scope="col">销售收入</th><th scope="col">每次预订收入</th><th scope="col">CPC</th><th scope="col">CVR</th><th scope="col">CPA</th><th scope="col">ROAS</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.name)}</th><td>${usd(r.cost,2)}</td><td>${num(r.impressions)}</td><td>${num(r.clicks)}</td><td>${pct(r.ctr)}</td><td>${num(r.bookings)}</td><td>${usd(r.revenue,2)}</td><td>${usd(r.revenuePerBooking,2)}</td><td>${usd(r.cpc,2)}</td><td>${pct(r.cvr)}</td><td>${usd(r.cpa,2)}</td><td>${num(r.roas,2)}×</td></tr>`).join('')}</tbody></table></div>`}
